function ProfileModal({ userId, onClose }) {
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    fetchProfile(userId).then((data) => {
      setProfile(data);
    });
  }, [userId]);

  if (!profile) return <Spinner />;
  return <ProfileCard profile={profile} onClose={onClose} />;
}

